#!/usr/bin/env node
'use strict';

const { MediaDownloader, MediaDownloaderError } = require('../src/index');
const pkg = require('../package.json');

const HELP = `
${pkg.name} v${pkg.version}
Download video, audio and images from any supported platform.

Usage:
  mediadownloader <url> [options]

Options:
  -o, --out <path>       Save to disk (treated as a directory if it ends in /)
  -t, --type <kind>      video or audio. Default: video
  -q, --quality <q>      best | worst | 360p | 720p | 1080p | ...
  -e, --endpoint <name>  Use a specific API endpoint
      --json             Print raw JSON
      --resolve          Resolve progress-stream links up front
      --base-url <url>   Point at your own deployment
  -h, --help             Show this help
  -v, --version          Show version
      --endpoints        List available endpoints

Examples:
  mediadownloader "https://www.tiktok.com/@user/video/123"
  mediadownloader "https://youtu.be/dQw4w9WgXcQ" -q 720p -o video.mp4
  mediadownloader "https://youtu.be/dQw4w9WgXcQ" -t audio -o ./downloads/
`;

function parseArgs(argv) {
  const options = {};
  const positional = [];

  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    const next = () => argv[++i];

    switch (arg) {
      case '-h': case '--help': options.help = true; break;
      case '-v': case '--version': options.version = true; break;
      case '--endpoints': options.listEndpoints = true; break;
      case '--json': options.json = true; break;
      case '--resolve': options.resolve = true; break;
      case '-o': case '--out': options.out = next(); break;
      case '-t': case '--type': options.type = next(); break;
      case '-q': case '--quality': options.quality = next(); break;
      case '-e': case '--endpoint': options.endpoint = next(); break;
      case '--base-url': options.baseUrl = next(); break;
      default:
        if (arg.startsWith('-')) {
          console.error(`Unknown option: ${arg}`);
          process.exit(1);
        }
        positional.push(arg);
    }
  }

  options.url = positional[0];
  return options;
}

function formatBytes(bytes) {
  if (bytes >= 1024 * 1024) return `${(bytes / 1024 / 1024).toFixed(2)} MB`;
  if (bytes >= 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${bytes} B`;
}

function formatDuration(seconds) {
  if (!seconds) return null;
  const mins = Math.floor(seconds / 60);
  const secs = seconds % 60;
  return `${mins}:${String(secs).padStart(2, '0')}`;
}

/** Single-line progress output for slow server-side encoding. */
function showProgress({ percent, status }) {
  const label = status === 'finalizing' ? 'merging' : 'encoding';
  process.stderr.write(`\r  ${label} ${percent}%   `);
}

async function main() {
  const options = parseArgs(process.argv.slice(2));

  if (options.version) {
    console.log(pkg.version);
    return;
  }

  if (options.listEndpoints) {
    console.log(MediaDownloader.endpoints.join('\n'));
    return;
  }

  if (options.help || !options.url) {
    console.log(HELP.trim());
    process.exit(options.help ? 0 : 1);
  }

  const client = new MediaDownloader({ baseUrl: options.baseUrl });

  if (options.out) {
    const saved = await client.save(options.url, options.out, {
      ...options,
      onProgress: options.json ? undefined : showProgress,
    });

    if (!options.json) process.stderr.write('\r                    \r');

    if (options.json) {
      console.log(JSON.stringify(saved, null, 2));
      return;
    }

    console.log(`Saved: ${saved.path}`);
    console.log(`Size:  ${formatBytes(saved.bytes)}`);
    return;
  }

  const result = await client.download(options.url, {
    ...options,
    onProgress: options.json ? undefined : showProgress,
  });

  if (result.pending && !options.resolve) process.stderr.write('');

  if (options.json) {
    console.log(JSON.stringify(result, null, 2));
    return;
  }

  console.log(`Platform: ${result.platform}  (endpoint: ${result.endpoint})`);
  if (result.title) console.log(`Title:    ${result.title}`);
  if (result.author) console.log(`Author:   ${result.author}`);
  if (result.duration) console.log(`Duration: ${formatDuration(result.duration)}`);
  console.log(`Media:    ${result.media.length} link(s)`);

  for (const item of result.media) {
    const quality = item.quality ? ` [${item.quality}]` : '';
    const pending = item.pending ? ' (needs --resolve)' : '';
    console.log(`  ${item.type.padEnd(5)}${quality}${pending}`);
    console.log(`        ${item.url}`);
  }

  if (result.pending && !options.resolve) {
    console.log('\nSome links stream encoding progress. Add --resolve to get direct URLs.');
  }
}

main().catch((error) => {
  process.stderr.write('\r');
  if (error instanceof MediaDownloaderError) {
    console.error(`[${error.code}] ${error.message}`);
  } else {
    console.error(`Error: ${error.message}`);
  }
  process.exit(1);
});
